/**
 * ElevenLabs voices of the user's account (F-1591): list and classify where
 * each voice came from. Read-only — nothing here creates, edits or deletes a
 * voice. Cloning lives in voice-clone.ts and is reachable only by the human
 * through trusted IPC, never by an MCP tool.
 */

export const ELEVENLABS_API = 'https://api.elevenlabs.io';

/**
 * - library: premade voice or one shared by someone else (the account does not own it)
 * - designed: generated by Voice Design, no person behind it
 * - nexus-clone: cloned through "Minha voz", with a consent receipt on this computer
 * - external-clone: a clone the account owns that the Nexus did not create
 */
export type VoiceOrigin = 'library' | 'designed' | 'nexus-clone' | 'external-clone' | 'unknown';

export interface ElevenLabsVoiceSummary {
  readonly voiceId: string;
  readonly name: string;
  readonly category: string;
  readonly origin: VoiceOrigin;
  /** language / accent / gender / age / use case, when the provider has them. */
  readonly labels: Readonly<Record<string, string>>;
  readonly languages: readonly string[];
  readonly description?: string;
}

interface RawVoice {
  voice_id?: unknown;
  name?: unknown;
  category?: unknown;
  is_owner?: unknown;
  labels?: unknown;
  description?: unknown;
  verified_languages?: unknown;
}

const LABEL_KEYS = ['language', 'accent', 'gender', 'age', 'use_case', 'descriptive'];
const MAX_PAGES = 5;

function text(value: unknown, max: number): string | undefined {
  if (typeof value !== 'string') return undefined;
  const clean = value.replace(/[\u0000-\u001f\u007f‪-‮⁦-⁩]+/gu, ' ').trim();
  return clean ? clean.slice(0, max) : undefined;
}

export function classifyVoiceOrigin(
  voice: { category?: unknown; is_owner?: unknown; voice_id?: unknown },
  isNexusClone: (voiceId: string) => boolean,
): VoiceOrigin {
  const category = typeof voice.category === 'string' ? voice.category : '';
  const id = typeof voice.voice_id === 'string' ? voice.voice_id : '';
  if (category === 'premade' || category === 'famous' || category === 'high_quality') return 'library';
  if (voice.is_owner === false) return 'library';
  if (category === 'generated') return 'designed';
  if (category === 'cloned' || category === 'professional') {
    return id && isNexusClone(id) ? 'nexus-clone' : 'external-clone';
  }
  return 'unknown';
}

export function summarizeVoice(
  raw: RawVoice,
  isNexusClone: (voiceId: string) => boolean,
): ElevenLabsVoiceSummary | null {
  const voiceId = text(raw.voice_id, 64);
  if (!voiceId || !/^[A-Za-z0-9_-]+$/u.test(voiceId)) return null;
  const labels: Record<string, string> = {};
  if (raw.labels && typeof raw.labels === 'object') {
    for (const key of LABEL_KEYS) {
      const value = text((raw.labels as Record<string, unknown>)[key], 40);
      if (value) labels[key] = value;
    }
  }
  const languages = Array.isArray(raw.verified_languages)
    ? [
        ...new Set(
          raw.verified_languages
            .map((entry) =>
              entry && typeof entry === 'object'
                ? text((entry as Record<string, unknown>).language, 12)
                : undefined,
            )
            .filter((value): value is string => Boolean(value)),
        ),
      ]
    : [];
  const description = text(raw.description, 200);
  return {
    voiceId,
    name: text(raw.name, 80) ?? voiceId,
    category: text(raw.category, 24) ?? 'unknown',
    origin: classifyVoiceOrigin(raw, isNexusClone),
    labels,
    languages,
    ...(description ? { description } : {}),
  };
}

async function providerFailure(res: Response, what: string): Promise<Error> {
  let detail = '';
  try {
    const body = (await res.json()) as { detail?: { message?: unknown } | unknown };
    const message =
      body.detail && typeof body.detail === 'object' && 'message' in body.detail
        ? (body.detail as { message?: unknown }).message
        : undefined;
    detail = text(message, 240) ?? '';
  } catch {
    // corpo ilegível: o status basta
  }
  if (res.status === 401) {
    return new Error(`A ElevenLabs recusou a chave ao ${what} (HTTP 401). Confira a chave em Ajustes → Serviços de mídia.`);
  }
  return new Error(`A ElevenLabs recusou ${what} (HTTP ${res.status})${detail ? `: ${detail}` : ''}`);
}

/** Every voice the account can use (up to 500), newest pages first as the API orders them. */
export async function listElevenLabsVoices(input: {
  key: string;
  fetchFn: typeof fetch;
  isNexusClone: (voiceId: string) => boolean;
  signal?: AbortSignal;
}): Promise<ElevenLabsVoiceSummary[]> {
  const voices: ElevenLabsVoiceSummary[] = [];
  let pageToken: string | null = null;
  for (let page = 0; page < MAX_PAGES; page += 1) {
    const url = new URL('/v2/voices', ELEVENLABS_API);
    url.searchParams.set('page_size', '100');
    url.searchParams.set('include_total_count', 'false');
    if (pageToken) url.searchParams.set('next_page_token', pageToken);
    const res = await input.fetchFn(url, {
      headers: { 'xi-api-key': input.key },
      signal: input.signal,
    });
    if (!res.ok) throw await providerFailure(res, 'a lista de vozes');
    const body = (await res.json()) as {
      voices?: unknown;
      has_more?: unknown;
      next_page_token?: unknown;
    };
    for (const raw of Array.isArray(body.voices) ? body.voices : []) {
      const summary = summarizeVoice(raw as RawVoice, input.isNexusClone);
      if (summary) voices.push(summary);
    }
    pageToken = body.has_more === true && typeof body.next_page_token === 'string'
      ? body.next_page_token
      : null;
    if (!pageToken) break;
  }
  return voices;
}

/** One voice by id; null when the account cannot see it. */
export async function getElevenLabsVoice(input: {
  key: string;
  voiceId: string;
  fetchFn: typeof fetch;
  isNexusClone: (voiceId: string) => boolean;
  signal?: AbortSignal;
}): Promise<ElevenLabsVoiceSummary | null> {
  const res = await input.fetchFn(
    new URL(`/v1/voices/${encodeURIComponent(input.voiceId)}`, ELEVENLABS_API),
    { headers: { 'xi-api-key': input.key }, signal: input.signal },
  );
  if (res.status === 404 || res.status === 400) return null;
  if (!res.ok) throw await providerFailure(res, 'os dados da voz');
  return summarizeVoice((await res.json()) as RawVoice, input.isNexusClone);
}
